import express from 'express';

const CENTER_VIEW_FUNCTION = Buffer.from('', 'base64').toString('utf8');

const previousSend = express.response.send;
express.response.send = function centerRepaymentSheetPatch(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';
    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      const start = body.indexOf('function showCenterView(id)');
      const end = body.indexOf('\nfunction downloadCenter', start);
      if (start !== -1 && end !== -1) {
        body = body.slice(0, start) + CENTER_VIEW_FUNCTION + body.slice(end);
      }
    }
  } catch (_) {}
  return previousSend.call(this, body);
};
